// Subject: Your receipt from Apple

import {
  Body,
  Column,
  Container,
  Head,
  Hr,
  Html,
  Preview,
  Row,
  Section,
  Tailwind,
  Text,
  Link,
} from "react-email";

import { ProductListSection as ProductCardSection } from "@/components/email/product-list";
import { createEmailTailwindConfig } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { appleTheme } from "@/components/email/theme-apple";

interface ReceiptItem {
  name: string;
  imageUrl?: string;
  price: string;
  quantity?: number;
}

interface Props {
  orderNumber?: string;
  customerName?: string;
  items?: ReceiptItem[];
  subtotal?: string;
  tax?: string;
  total?: string;
  supportHref?: string;
  _productName?: string;
}

export const ReceiptApple = ({
  orderNumber = "ORD-123",
  customerName = "John",
  items = [{ name: "iPhone 15 Pro", price: "$999.00", quantity: 1 }],
  subtotal = "$999.00",
  tax = "$79.92",
  total = "$1078.92",
  supportHref = "#",
  _productName = "Apple",
}: Props) => {
  void _productName;

  const t = appleTheme;

  return (
    <Html>
      <Head />
      <Preview>Your receipt</Preview>
      <Tailwind config={createEmailTailwindConfig(t)}>
        <Body className="bg-background font-sans">
          <Container className="mx-auto max-w-container p-8">
            <Section className="py-12">
              <Text className="mb-1 text-3xl font-bold tracking-tight text-foreground">
                Receipt
              </Text>
              <Text className="mb-8 text-base text-foreground-muted">
                Order {orderNumber} • {customerName}
              </Text>
            </Section>

            <Section>
              {items.map((item, index) => (
                <ProductCardSection
                  key={`${item.name}-${index}`}
                  products={[
                    {
                      imageUrl: item.imageUrl,
                      name: item.name,
                      price: item.price,
                      quantity: item.quantity,
                    },
                  ]}
                />
              ))}
            </Section>

            <Section className="mt-4">
              <Row>
                <Column>
                  <Text className="text-base text-foreground-muted">
                    Subtotal
                  </Text>
                </Column>
                <Column align="right">
                  <Text className="text-right text-base font-medium text-foreground">
                    {subtotal}
                  </Text>
                </Column>
              </Row>
              <Row>
                <Column>
                  <Text className="text-base text-foreground-muted">Tax</Text>
                </Column>
                <Column align="right">
                  <Text className="text-right text-base font-medium text-foreground">
                    {tax}
                  </Text>
                </Column>
              </Row>
              <Hr className="my-4 border-border" />
              <Row>
                <Column>
                  <Text className="text-lg font-bold text-foreground">
                    Total
                  </Text>
                </Column>
                <Column align="right">
                  <Text className="text-right text-lg font-bold text-foreground">
                    {total}
                  </Text>
                </Column>
              </Row>
            </Section>

            <Text className="mt-8 text-sm text-foreground-muted">
              Need help?{" "}
              <Link href={supportHref} className="text-foreground underline">
                Contact Apple Support
              </Link>
            </Text>
          </Container>
        </Body>
      </Tailwind>
    </Html>
  );
};

ReceiptApple.PreviewProps = {
  _productName: "Apple",
  customerName: "John Doe",
  items: [
    {
      imageUrl: emailAsset("products/product-1.jpg"),
      name: "iPhone 15 Pro",
      price: "$999.00",
      quantity: 1,
    },
  ],
  orderNumber: "ORD-12345",
  subtotal: "$999.00",
  supportHref: "https://example.com/support",
  tax: "$79.92",
  total: "$1078.92",
} satisfies Props;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
